702	func (h *postCommitActionHandler) shouldCondenseWithOverlapCheck(isActive bool, lastInteraction *time.Time) bool {
703		if !h.hasNew {
704			return false
705		}
706		// ACTIVE sessions with recent interaction: skip the overlap check.
707		// PrepareCommitMsg already validated this commit is session-related
708		// (added trailer). The overlap check is only meaningful when we need
709		// heuristic evidence that a commit was related to the session.
710		//
711		// Exception: when another session's tracked files overlap with the
712		// committed files, skip this ACTIVE session if it has no tracked files
713		// itself. This prevents read-only sessions (e.g., codex exec from tools
714		// like summarize) from being condensed when a different session's commit
715		// triggers PostCommit. When no other session claims the committed files,
716		// the ACTIVE session is assumed to own the commit.
717		//
718		// We check LastInteractionTime to avoid condensing stale ACTIVE sessions
719		// (agent killed without Stop hook) into every subsequent commit. A stale
720		// session has no recent interaction and falls through to the overlap check.
721		if isActive && isRecentInteraction(lastInteraction) {
722			if h.sessionsWithCommittedFiles > 0 && len(h.filesTouchedBefore) == 0 {
723				logging.Debug(h.ctx, "post-commit: skipping read-only ACTIVE session (no tracked files, other sessions claim committed files)",
724					slog.Int("sessions_with_committed_files", h.sessionsWithCommittedFiles),
725				)
726				return false
727			}
728			return true
729		}
730		if len(h.filesTouchedBefore) == 0 {
731			return false // No files tracked = no overlap evidence
732		}
733		// Only check files that were actually changed in this commit.
734		// Without this, files that exist in the tree but weren't changed
735		// would pass the "modified file" check in filesOverlapWithContent
736		// (because the file exists in the parent tree), causing stale
737		// sessions to be incorrectly condensed.
738		var committedTouchedFiles []string
739		for _, f := range h.filesTouchedBefore {
740			if _, ok := h.committedFileSet[f]; ok {
741				committedTouchedFiles = append(committedTouchedFiles, f)
742			}
743		}
744		if len(committedTouchedFiles) == 0 {
745			return false
746		}
747		return filesOverlapWithContent(h.ctx, h.repo, h.shadowBranchName, h.commit, committedTouchedFiles, overlapOpts{
748			headTree:      h.headTree,
749			shadowTree:    h.shadowTree,
750			parentTree:    h.parentTree,
751			hasParentTree: true,
752		})
753	}
