3	// CapabilityDeclarer is implemented by agents that declare their capabilities
4	// at registration time (e.g., external plugin agents). The As* helper functions
5	// below use this interface to gate capability access: an agent must both implement
6	// the optional interface AND declare the capability as true.
7	//
8	// Built-in agents (Claude Code, Gemini CLI, etc.) do NOT implement this interface.
9	// For those agents, the As* helpers fall through to a direct type assertion,
10	// preserving existing behavior.
11	type CapabilityDeclarer interface {
12		DeclaredCapabilities() DeclaredCaps
13	}
14	
15	// DeclaredCaps enumerates the optional interfaces an agent claims to support.
16	// JSON tags match the external agent protocol schema so external.InfoResponse
17	// can deserialize directly into this type.
18	type DeclaredCaps struct {
19		Hooks                  bool `json:"hooks"`
20		TranscriptAnalyzer     bool `json:"transcript_analyzer"`
21		TranscriptPreparer     bool `json:"transcript_preparer"`
22		TokenCalculator        bool `json:"token_calculator"`
23		TextGenerator          bool `json:"text_generator"`
24		HookResponseWriter     bool `json:"hook_response_writer"`
25		SubagentAwareExtractor bool `json:"subagent_aware_extractor"`
26	}
