28	// AsHookSupport returns the agent as HookSupport if it both implements the
29	// interface and (for CapabilityDeclarer agents) has declared the capability.
30	func AsHookSupport(ag Agent) (HookSupport, bool) { //nolint:ireturn // type-assertion helper must return interface
31		if ag == nil {
32			return nil, false
33		}
34		hs, ok := ag.(HookSupport)
35		if !ok {
36			return nil, false
37		}
38		if cd, ok := ag.(CapabilityDeclarer); ok {
39			return hs, cd.DeclaredCapabilities().Hooks
40		}
41		return hs, true
42	}
