737		data := &ExtractedSessionData{}
738	
739		ag, _ := agent.GetByAgentType(state.AgentType) //nolint:errcheck // ag may be nil for unknown agent types; callers use type assertions so nil is safe
740	
741		// Resolve the transcript path (handles agents that relocate mid-session).
742		transcriptPath, resolveErr := resolveTranscriptPath(state)
743		if resolveErr != nil {
744			return nil, resolveErr
745		}
746	
747		liveData, err := os.ReadFile(transcriptPath) //nolint:gosec // path validated by resolveTranscriptPath
748		if err != nil {
749			return nil, fmt.Errorf("failed to read live transcript: %w", err)
750		}
751	
752		if len(liveData) == 0 {
753			return nil, errors.New("live transcript is empty")
754		}
755	
756		fullTranscript := string(liveData)
757		data.Transcript = liveData
758		data.FullTranscriptLines = countTranscriptItems(state.AgentType, fullTranscript)
759		data.Prompts = readPromptsFromFilesystem(ctx, state.SessionID)
760	
761		// Resolve files touched: prefers hook-populated state, falls back to transcript extraction
762		data.FilesTouched = s.resolveFilesTouched(ctx, state)
763	
764		// Calculate token usage from the extracted transcript portion
765		if len(data.Transcript) > 0 {
766			data.TokenUsage = agent.CalculateTokenUsage(ctx, ag, data.Transcript, state.CheckpointTranscriptStart, "") //TODO: why do we not use here subagents dir?
767		}
768	
769		return data, nil
770	}
