772	// countTranscriptItems counts lines (JSONL) or messages (JSON) in a transcript.
773	// For Claude Code and JSONL-based agents, this counts lines.
774	// For Gemini CLI, OpenCode, and JSON-based agents, this counts messages.
775	// Returns 0 if the content is empty or malformed.
776	func countTranscriptItems(agentType types.AgentType, content string) int {
777		if content == "" {
778			return 0
779		}
780	
781		// OpenCode uses export JSON format with {"info": {...}, "messages": [...]}
782		if agentType == agent.AgentTypeOpenCode {
783			session, err := opencode.ParseExportSession([]byte(content))
784			if err == nil && session != nil {
785				return len(session.Messages)
786			}
787			return 0
788		}
789	
790		// Try Gemini format first if agentType is Gemini, or as fallback if Unknown
791		if agentType == agent.AgentTypeGemini || agentType == agent.AgentTypeUnknown {
792			transcript, err := geminicli.ParseTranscript([]byte(content))
793			if err == nil && transcript != nil && len(transcript.Messages) > 0 {
794				return len(transcript.Messages)
795			}
796			// If agentType is explicitly Gemini but parsing failed, return 0
797			if agentType == agent.AgentTypeGemini {
798				return 0
799			}
800			// Otherwise fall through to JSONL parsing for Unknown type
801		}
802	
803		// Claude Code and other JSONL-based agents
804		allLines := strings.Split(content, "\n")
805		// Trim trailing empty lines (from final \n in JSONL)
806		for len(allLines) > 0 && strings.TrimSpace(allLines[len(allLines)-1]) == "" {
807			allLines = allLines[:len(allLines)-1]
808		}
809		return len(allLines)
810	}
