293		// Read existing summary to get current session count
294		var existingSummary *CheckpointSummary
295		metadataPath := basePath + paths.MetadataFileName
296		if entry, exists := entries[metadataPath]; exists {
297			existing, err := s.readSummaryFromBlob(entry.Hash)
298			if err == nil {
299				existingSummary = existing
300			}
301		}
302	
303		// Determine session index: reuse existing slot if session ID matches, otherwise append
304		sessionIndex := s.findSessionIndex(ctx, basePath, existingSummary, entries, opts.SessionID)
305	
306		// Write session files to numbered subdirectory
307		sessionPath := fmt.Sprintf("%s%d/", basePath, sessionIndex)
308		sessionFilePaths, err := s.writeSessionToSubdirectory(ctx, opts, sessionPath, entries)
309		if err != nil {
310			return err
311		}
312	
313		// Copy additional metadata files from directory if specified (to session subdirectory)
314		if opts.MetadataDir != "" {
315			if err := s.copyMetadataDir(opts.MetadataDir, sessionPath, entries); err != nil {
316				return fmt.Errorf("failed to copy metadata directory: %w", err)
317			}
318		}
319	
320		// Build the sessions array
321		var sessions []SessionFilePaths
322		if existingSummary != nil {
323			sessions = make([]SessionFilePaths, max(len(existingSummary.Sessions), sessionIndex+1))
324			copy(sessions, existingSummary.Sessions)
325		} else {
326			sessions = make([]SessionFilePaths, 1)
327		}
328		sessions[sessionIndex] = sessionFilePaths
