// fakeExternalAgentType is an agent type NOT registered in the built-in registry,
// simulating an external agent (like Pi) whose transcript is only accessible via
// the ReadTranscript binary subcommand — NOT as a file on disk.
const fakeExternalAgentType types.AgentType = "Fake External Agent"
const fakeExternalAgentName types.AgentName = "fake-external"

// fakeExternalAgent is a minimal Agent implementation that serves transcript
// data via ReadTranscript() but does NOT write any file to disk.
// This simulates external agents (like Pi) where the transcript is only
// available through the agent binary's read-transcript subcommand.
type fakeExternalAgent struct {
	transcript []byte
}

func (f *fakeExternalAgent) Name() types.AgentName                              { return fakeExternalAgentName }
func (f *fakeExternalAgent) Type() types.AgentType                              { return fakeExternalAgentType }
func (f *fakeExternalAgent) Description() string                                { return "Fake external agent for testing" }
func (f *fakeExternalAgent) IsPreview() bool                                    { return false }
func (f *fakeExternalAgent) DetectPresence(_ context.Context) (bool, error)     { return true, nil }
func (f *fakeExternalAgent) ProtectedDirs() []string                            { return nil }
func (f *fakeExternalAgent) ReadTranscript(_ string) ([]byte, error)            { return f.transcript, nil }
func (f *fakeExternalAgent) ChunkTranscript(_ context.Context, c []byte, _ int) ([][]byte, error) {
	return [][]byte{c}, nil
}
func (f *fakeExternalAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
	if len(chunks) == 1 {
		return chunks[0], nil
	}
	return nil, nil
}
func (f *fakeExternalAgent) GetSessionID(_ *agent.HookInput) string          { return "" }
func (f *fakeExternalAgent) GetSessionDir(_ string) (string, error)          { return "", nil }
func (f *fakeExternalAgent) ResolveSessionFile(_, id string) string          { return id }
func (f *fakeExternalAgent) ReadSession(_ *agent.HookInput) (*agent.AgentSession, error) {
	return nil, nil
}
func (f *fakeExternalAgent) WriteSession(_ context.Context, _ *agent.AgentSession) error { return nil }
func (f *fakeExternalAgent) FormatResumeCommand(_ string) string             { return "" }

// TestCondenseSession_ExternalAgent_NoShadowBranch_TranscriptNotOnDisk verifies
// that CondenseSession fails for external agents when:
// 1. No shadow branch exists (SaveStep hasn't been called — agent is mid-turn)
// 2. The transcript is NOT available as a file on disk (external agents serve
//    transcripts via their read-transcript binary subcommand, not as files)
//
// This is the bug reported for Pi: prepare-commit-msg adds the Entire-Checkpoint
// trailer (because the session is ACTIVE), but post-commit's condensation fails
// silently because extractSessionDataFromLiveTranscript uses os.ReadFile()
// directly instead of ag.ReadTranscript().
//
// The fix: extractSessionDataFromLiveTranscript should use ag.ReadTranscript()
// when the agent is available, falling back to os.ReadFile() only for nil agents.
func TestCondenseSession_ExternalAgent_NoShadowBranch_TranscriptNotOnDisk(t *testing.T) {
	dir := setupGitRepo(t)
	t.Chdir(dir)

	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)

	// Register fake external agent so GetByAgentType resolves it.
	transcriptContent := []byte(testTranscriptPromptResponse)
	fakeAgent := &fakeExternalAgent{transcript: transcriptContent}
	agent.Register(fakeExternalAgentName, func() agent.Agent { return fakeAgent })
	t.Cleanup(func() { agent.Unregister(fakeExternalAgentName) })

	s := &ManualCommitStrategy{}
	sessionID := "test-external-no-shadow"

	worktreePath, err := paths.WorktreeRoot(context.Background())
	require.NoError(t, err)
	worktreeID, err := paths.GetWorktreeID(worktreePath)
	require.NoError(t, err)

	head, err := repo.Head()
	require.NoError(t, err)

	now := time.Now()

	// Set TranscriptPath to a path that does NOT exist on disk.
	// This simulates an external agent whose transcript is only available
	// via the read-transcript binary subcommand.
	nonExistentTranscriptPath := filepath.Join(dir, "pi-sessions", "nonexistent-transcript.jsonl")

	state := &SessionState{
		SessionID:                 sessionID,
		BaseCommit:                head.Hash().String(),
		WorktreePath:              worktreePath,
		WorktreeID:                worktreeID,
		StartedAt:                 now,
		Phase:                     session.PhaseActive,
		LastInteractionTime:       &now,
		AgentType:                 fakeExternalAgentType,
		TranscriptPath:            nonExistentTranscriptPath,
		CheckpointTranscriptStart: 0,
	}
	require.NoError(t, s.saveSessionState(context.Background(), state))

	// Generate checkpoint ID (same as what prepare-commit-msg would produce)
	checkpointID, err := id.Generate()
	require.NoError(t, err)

	// Call CondenseSession directly — no shadow branch exists, transcript
	// is not on disk, but IS available via ReadTranscript().
	result, err := s.CondenseSession(context.Background(), repo, checkpointID, state, nil)
	require.NoError(t, err, "CondenseSession should succeed for external agents "+
		"by using ag.ReadTranscript() when the transcript file is not on disk")
	require.NotNil(t, result)

	// Verify checkpoint was written to entire/checkpoints/v1
	sessionsRef, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
	require.NoError(t, err, "entire/checkpoints/v1 branch should exist after condensation")
	assert.NotNil(t, sessionsRef)
}

// TestPostCommit_ExternalAgent_MidTurnCommit_CondensesWithoutFile is an
// end-to-end test verifying the full PostCommit flow for an external agent
// making commits mid-turn (like Pi running /autoresearch overnight).
//
// Setup:
// - ACTIVE session for a fake external agent
// - No shadow branch (SaveStep not called — agent is mid-turn)
// - Transcript only available via ReadTranscript(), not on disk
// - Commit made with Entire-Checkpoint trailer
//
// Expected: PostCommit should condense the session using ag.ReadTranscript()
// and the checkpoint should be findable on entire/checkpoints/v1.
func TestPostCommit_ExternalAgent_MidTurnCommit_CondensesWithoutFile(t *testing.T) {
	dir := setupGitRepo(t)
	t.Chdir(dir)

	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)

	// Register fake external agent.
	transcriptContent := []byte(testTranscriptPromptResponse)
	fakeAgent := &fakeExternalAgent{transcript: transcriptContent}
	agent.Register(fakeExternalAgentName, func() agent.Agent { return fakeAgent })
	t.Cleanup(func() { agent.Unregister(fakeExternalAgentName) })

	s := &ManualCommitStrategy{}
	sessionID := "test-external-midturn-commit"

	worktreePath, err := paths.WorktreeRoot(context.Background())
	require.NoError(t, err)
	worktreeID, err := paths.GetWorktreeID(worktreePath)
	require.NoError(t, err)

	head, err := repo.Head()
	require.NoError(t, err)

	now := time.Now()

	// Transcript path that doesn't exist on disk (external agent serves via binary).
	nonExistentPath := filepath.Join(dir, "pi-data", "transcript.jsonl")

	state := &SessionState{
		SessionID:                 sessionID,
		BaseCommit:                head.Hash().String(),
		WorktreePath:              worktreePath,
		WorktreeID:                worktreeID,
		StartedAt:                 now,
		Phase:                     session.PhaseActive,
		LastInteractionTime:       &now,
		AgentType:                 fakeExternalAgentType,
		TranscriptPath:            nonExistentPath,
		CheckpointTranscriptStart: 0,
	}
	require.NoError(t, s.saveSessionState(context.Background(), state))

	// Create a commit with a checkpoint trailer (simulates agent committing mid-turn)
	checkpointIDStr := "a1b2c3d4e5f6"
	commitWithCheckpointTrailer(t, repo, dir, checkpointIDStr)

	// Run PostCommit — this is the full code path that would be triggered by
	// the post-commit git hook.
	err = s.PostCommit(context.Background())
	require.NoError(t, err)

	// Verify condensation happened: entire/checkpoints/v1 branch should exist
	// with the checkpoint data.
	sessionsRef, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
	require.NoError(t, err, "entire/checkpoints/v1 branch should exist — condensation should "+
		"have used ag.ReadTranscript() since the transcript file is not on disk")
	assert.NotNil(t, sessionsRef)

	// Verify session state was updated (condensation succeeded)
	updatedState, err := s.loadSessionState(context.Background(), sessionID)
	require.NoError(t, err)
	require.NotNil(t, updatedState)
	assert.Equal(t, session.PhaseActive, updatedState.Phase,
		"session should remain ACTIVE after mid-turn condensation")
	assert.Equal(t, checkpointIDStr, updatedState.LastCheckpointID.String(),
		"LastCheckpointID should be set after successful condensation")
}

