// fakeExternalAgentWithTranscript extends fakeExternalAgent to serve transcript
// data via ReadTranscript() and implements TranscriptAnalyzer.
type fakeExternalAgentWithTranscript struct {
	fakeExternalAgent

	transcript    []byte
