// TestPostCommit_ExternalAgent_ReadOnlyHeuristic_BlocksCondensation verifies
// the bug where an external agent's (Pi) condensation is skipped due to the
// read-only session heuristic when a concurrent session exists.
//
// Scenario (reproduces the reported Pi bug):
// 1. Session A (Claude Code, IDLE) — has FilesTouched from a previous SaveStep
// 2. Session B (Pi, ACTIVE) — mid-turn, FilesTouched cleared by prior condensation
// 3. Pi commits files that overlap with session A's FilesTouched
// 4. PostCommit: sessionsWithCommittedFiles > 0 (from session A's state.FilesTouched)
// 5. PostCommit: Pi's filesTouchedBefore is empty because extractModifiedFilesFromOffset
//    finds no NEW file modifications in the transcript since the last condensation
//    (agent modified files before commit 1, only did research between commits)
// 6. shouldCondenseWithOverlapCheck: sessionsWithCommittedFiles > 0 && filesTouchedBefore == 0
//    → returns false → Pi's condensation skipped → dangling Entire-Checkpoint trailer
//
// The fix should ensure that ACTIVE sessions with recent interaction are ALWAYS
// condensed, regardless of whether other sessions claim the committed files.
func TestPostCommit_ExternalAgent_ReadOnlyHeuristic_BlocksCondensation(t *testing.T) {
	dir := setupGitRepo(t)
	t.Chdir(dir)

	repo, err := git.PlainOpen(dir)
	require.NoError(t, err)

	// Register fake external agent (simulates Pi with transcript_analyzer).
	const piAgentName types.AgentName = "fake-pi-readonly"
	const piAgentType types.AgentType = "Fake Pi Readonly"
	transcriptContent := []byte(testTranscriptPromptResponse)
	piAgent := &fakeExternalAgentWithTranscript{
		fakeExternalAgent: fakeExternalAgent{name: piAgentName, agentType: piAgentType},
		transcript:        transcriptContent,
		modifiedFiles:     nil, // No new file modifications since last condensation offset
	}
	agent.Register(piAgentName, func() agent.Agent { return piAgent })

	s := &ManualCommitStrategy{}

	worktreePath, err := paths.WorktreeRoot(context.Background())
	require.NoError(t, err)
	worktreeID, err := paths.GetWorktreeID(worktreePath)
	require.NoError(t, err)

	head, err := repo.Head()
	require.NoError(t, err)

	now := time.Now()
	baseCommit := head.Hash().String()

	// --- Session A: Claude Code session (IDLE), has FilesTouched overlapping committed files ---
	sessionA := "session-a-claudecode"
	stateA := &SessionState{
		SessionID:           sessionA,
		BaseCommit:          baseCommit,
		WorktreePath:        worktreePath,
		WorktreeID:          worktreeID,
		StartedAt:           now.Add(-1 * time.Hour),
		Phase:               session.PhaseIdle,
		LastInteractionTime: &now,
		AgentType:           agent.AgentTypeClaudeCode,
		FilesTouched:        []string{"test.txt"}, // Claims the committed file
	}
	require.NoError(t, s.saveSessionState(context.Background(), stateA))

	// --- Session B: Pi session (ACTIVE), mid-turn, FilesTouched cleared ---
	sessionB := "session-b-pi"

	// Write Pi's transcript to disk (external agents always use files)
	transcriptPath := filepath.Join(dir, ".pi", "sessions", "transcript.jsonl")
	require.NoError(t, os.MkdirAll(filepath.Dir(transcriptPath), 0o755))
	require.NoError(t, os.WriteFile(transcriptPath, transcriptContent, 0o644))

	// Create prompt file so condensation has prompt data
	promptDir := filepath.Join(dir, ".entire", "metadata", sessionB)
	require.NoError(t, os.MkdirAll(promptDir, 0o755))
	require.NoError(t, os.WriteFile(filepath.Join(promptDir, "prompt.txt"), []byte("run /autoresearch"), 0o644))

	stateB := &SessionState{
		SessionID:                 sessionB,
		BaseCommit:                baseCommit,
		WorktreePath:              worktreePath,
		WorktreeID:                worktreeID,
		StartedAt:                 now,
		Phase:                     session.PhaseActive,
		LastInteractionTime:       &now,
		AgentType:                 piAgentType,
		TranscriptPath:            transcriptPath,
		CheckpointTranscriptStart: 2, // Offset past current content (simulates prior condensation)
		FilesTouched:              nil, // Cleared by prior condensation
	}
	require.NoError(t, s.saveSessionState(context.Background(), stateB))

	// Commit with checkpoint trailer (simulates Pi committing test.txt mid-turn)
	checkpointIDStr := "a1b2c3d4e5f6"
	commitWithCheckpointTrailer(t, repo, dir, checkpointIDStr)

	// Run PostCommit
	err = s.PostCommit(context.Background())
	require.NoError(t, err)

	// Verify Pi's checkpoint was condensed to entire/checkpoints/v1
	sessionsRef, err := repo.Reference(plumbing.NewBranchReferenceName(paths.MetadataBranchName), true)
	require.NoError(t, err, "entire/checkpoints/v1 branch should exist — "+
		"Pi's ACTIVE session should be condensed even when another session claims the committed files")
	assert.NotNil(t, sessionsRef)

	// Verify the checkpoint is actually findable (the whole point — entire explain needs this)
	store := checkpoint.NewGitStore(repo)
	committed, err := store.ListCommitted(context.Background())
	require.NoError(t, err)

	cpID, err := id.ParseCheckpointID(checkpointIDStr)
	require.NoError(t, err)

	var found bool
	for _, c := range committed {
		if c.CheckpointID == cpID {
			found = true
			break
		}
	}
	assert.True(t, found, "checkpoint %s should be findable on entire/checkpoints/v1 — "+
		"this is what 'entire explain' uses to resolve Entire-Checkpoint trailers", checkpointIDStr)

	// Verify Pi's session state was updated
	updatedB, err := s.loadSessionState(context.Background(), sessionB)
	require.NoError(t, err)
	require.NotNil(t, updatedB)
	assert.Equal(t, session.PhaseActive, updatedB.Phase)
	assert.Equal(t, checkpointIDStr, updatedB.LastCheckpointID.String(),
		"LastCheckpointID should be set after successful condensation")
}

